* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  font-family: system-ui, sans-serif;
  color: #172b42;
  background: radial-gradient(circle at 20% 20%, #c5e9ef, transparent 65%), #e6e7f4;
}

.counter {
  width: min(100%, 360px);
  padding: 32px;
  text-align: center;
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid #fff;
  border-radius: 24px;
  box-shadow: 0 16px 48px rgba(23, 43, 66, 0.12);
  backdrop-filter: blur(12px);
}

h1 { margin: 0 0 24px; font-size: 1.5rem; }
p { margin: 0; }
output {
  display: block;
  margin: 12px 0 28px;
  font-size: 4rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.controls { display: flex; flex-wrap: wrap; gap: 12px; }
button {
  flex: 1 1 110px;
  min-height: 48px;
  padding: 12px 16px;
  border: 2px solid #234b70;
  border-radius: 12px;
  background: #234b70;
  color: #fff;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: transform 120ms ease;
}
#reset { background: #fff; color: #234b70; }
button:hover { transform: translateY(-2px); }
button:active { transform: translateY(0); }
button:focus-visible { outline: 3px solid #172b42; outline-offset: 4px; }
noscript { display: block; margin-top: 20px; }

@media (prefers-reduced-motion: reduce) {
  button { transition: none; }
  button:hover { transform: none; }
}

'use strict';

let count = 0;
const display = document.getElementById('count');

function render() {
  display.textContent = String(count);
}

document.getElementById('increment').addEventListener('click', () => {
  count += 1;
  render();
});

document.getElementById('reset').addEventListener('click', () => {
  count = 0;
  render();
});
